{
  "items": [
    {
      "name": "Polynomial.hasseDeriv_zero'",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (f : Polynomial R), (Polynomial.hasseDeriv 0) f = f"
    },
    {
      "name": "Polynomial.hasseDeriv_zero",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R], Polynomial.hasseDeriv 0 = LinearMap.id"
    },
    {
      "name": "Polynomial.hasseDeriv",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : Semiring R] → ℕ → Polynomial R →ₗ[R] Polynomial R"
    },
    {
      "name": "LaurentSeries.hasseDeriv_zero",
      "module_name": "Mathlib.RingTheory.LaurentSeries",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] {V : Type u_2} [inst_1 : AddCommGroup V] [inst_2 : Module R V],\n  LaurentSeries.hasseDeriv R 0 = LinearMap.id"
    },
    {
      "name": "Polynomial.hasseDeriv_apply",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (k : ℕ) (f : Polynomial R),\n  (Polynomial.hasseDeriv k) f = f.sum fun i r => (Polynomial.monomial (i - k)) (↑(i.choose k) * r)"
    },
    {
      "name": "Polynomial.hasseDeriv_eq_zero_of_lt_natDegree",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (p : Polynomial R) (n : ℕ), p.natDegree < n → (Polynomial.hasseDeriv n) p = 0"
    },
    {
      "name": "Polynomial.hasseDeriv_one",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R], Polynomial.hasseDeriv 1 = Polynomial.derivative"
    },
    {
      "name": "LaurentSeries.derivative_apply",
      "module_name": "Mathlib.RingTheory.LaurentSeries",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] {V : Type u_2} [inst_1 : AddCommGroup V] [inst_2 : Module R V]\n  (f : LaurentSeries V), (LaurentSeries.derivative R) f = (LaurentSeries.hasseDeriv R 1) f"
    }
  ]
}
